import sys; sys.path.insert(0, str(WORK))
from cvlib import *
R = np.load(WORK/'base_reads.npz'); y=R['y']; res=np.load(WORK/'reserved.npy')
keep = np.setdiff1d(np.arange(768), res)
M = lambda L: R[f'mean_hidden_L{L}'][:,keep]
Y=np.eye(8)[y]
def kcv_fn(X, transform, kfun, lam=1e-2, seeds=(0,1,2)):
    out=[]
    for s in seeds:
        f=folds(y,5,s); S=np.zeros((len(y),8))
        for i in range(5):
            tr=f!=i; te=f==i
            Z=transform(X, tr)
            Z=Z/np.linalg.norm(Z,axis=1,keepdims=True)
            K=kfun(Z@Z[tr].T)
            A=np.linalg.solve(K[tr]+lam*np.eye(tr.sum()), Y[tr]-Y[tr].mean(0)); S[te]=K[te]@A
        out.append((S.argmax(1)==y).mean())
    return round(float(np.mean(out)),4)
def zt(X,tr):
    return (X-X[tr].mean(0))/(X[tr].std(0)+1e-6)
def lda_t(shr, ncomp=None):
    def t(X,tr):
        mu=X[tr].mean(0); means=np.stack([X[tr][y[tr]==c].mean(0) for c in range(8)])
        Xc=X[tr]-means[y[tr]]; Sw=Xc.T@Xc/len(Xc); Sw=(1-shr)*Sw+shr*np.trace(Sw)/Sw.shape[0]*np.eye(Sw.shape[0])
        ev,EV=np.linalg.eigh(Sw); Wh=EV/np.sqrt(ev)
        return (X-mu)@Wh
    return t
def pca_t(k, whiten=True):
    def t(X,tr):
        mu=X[tr].mean(0); U,s,Vt=np.linalg.svd(X[tr]-mu, full_matrices=False)
        Z=(X-mu)@Vt[:k].T
        return Z/s[:k]*np.sqrt(len(tr)) if whiten else Z
    return t
q=lambda C: C+0.5*C**2
for L in [0,1]:
    X=M(L)
    print(L,'z quad', kcv_fn(X,zt,q))
    for a in [0.25,1,2]:
        print(L,'z C+aC^2',a, kcv_fn(X,zt,lambda C: C+a*C**2))
    print(L,'z cubic', kcv_fn(X,zt,lambda C: C+0.5*C**2+C**3/6))
    for shr in [0.1,0.3]:
        print(L,'lda-whiten quad', shr, kcv_fn(X,lda_t(shr),q))
    for k in [64,128,256]:
        print(L,'pca-white',k, kcv_fn(X,pca_t(k),q), 'pca raw', kcv_fn(X,pca_t(k,False),q))
